// Code Node: Подготовка одного рецепта для OpenAI Embeddings
// Размещается после Split In Batches, перед HTTP Request к OpenAI

const recipe = $input.first().json;


// Создаем текст для эмбеддинга
const fullText = `Рецепт: ${recipe.name}\n\nСодержание: ${recipe.content}`;

// Ограничиваем размер текста (OpenAI имеет лимит ~8191 токенов)
// Примерно 1 токен = 4 символа, оставляем запас
const MAX_CHARS = 7000; // ~1750 токенов

let embeddingText;
if (fullText.length <= MAX_CHARS) {
  embeddingText = fullText;
  console.log(`Текст помещается: ${fullText.length} символов`);
} else {
  // Обрезаем по границе слов
  const truncated = fullText.substring(0, MAX_CHARS);
  const lastSpaceIndex = truncated.lastIndexOf(' ');

  // Если последний пробел не слишком далеко, обрезаем по нему
  if (lastSpaceIndex > MAX_CHARS * 0.9) {
    embeddingText = truncated.substring(0, lastSpaceIndex) + '...';
  } else {
    embeddingText = truncated + '...';
  }

  console.log(`Текст обрезан: ${fullText.length} → ${embeddingText.length} символов`);
}

// Возвращаем данные для OpenAI
return [{
  json: {
    model: "text-embedding-3-small",
    input: embeddingText,
    // Сохраняем оригинальные данные рецепта для следующего шага
    recipe_data: {
      id: recipe.id,
      number: recipe.number,
      name: recipe.name,
      content: recipe.content,
      full_text: recipe.full_text,
      sparse_vectors: recipe.sparse_vectors,
      // Добавляем информацию об обрезке
      was_truncated: fullText.length > MAX_CHARS,
      original_length: fullText.length,
      embedding_length: embeddingText.length
    }
  }
}];

// Полный парсер всех рецептов водок из исторического документа
console.log('=== ПАРСИНГ ВСЕХ РЕЦЕПТОВ ===');

try {
  const inputData = $input.first();

  if (!inputData?.json?.content) {
    return [{ json: { error: 'No content field found' } }];
  }

  const fullText = inputData.json.content;
  console.log(`Полный текст: ${fullText.length} символов`);

  // Полная функция парсинга всех рецептов
  function parseAllWaterRecipes(text) {
    const recipes = [];

    try {
      console.log('Поиск всех рецептов в документе...');

      // Основной паттерн: **номер. название**
      const mainPattern = /\*\*(\d+)\.\s*([^*\n]+?)\*\*\s*([\s\S]*?)(?=\*\*\d+\.|$)/g;
      let match;
      let foundCount = 0;

      while ((match = mainPattern.exec(text)) !== null && foundCount < 300) {
        const number = parseInt(match[1]);
        let name = match[2].trim().replace(/\.$/, ''); // Убираем точку в конце
        let content = match[3].trim();

        // Убираем лишние переносы в начале контента
        content = content.replace(/^\s*\n+/, '');

        // Фильтруем заголовки глав
        if (name.includes('ГЛАВА') || 
            name.includes('Водки тминные') || 
            name.includes('Водки анисовые') ||
            name.includes('Водки ировые') ||
            name.includes('Водки померанцевые') ||
            name.includes('Водки фенхельные') ||
            name.includes('Водки розмариновые') ||
            name.includes('Полынные водки') ||
            name.includes('Водки из кудрявой мяты') ||
            name.includes('Лимонные водки') ||
            name.includes('Водки коричные') ||
            name.includes('Водки можжевеловые') ||
            name.includes('Водки мелиссные') ||
            name.includes('Водки дягилевые') ||
            name.includes('Водки девясильные') ||
            name.includes('Водки гвоздичные') ||
            name.includes('Водки цитварные') ||
            name.includes('Водки карминативные') ||
            name.includes('Водки желудочные') ||
            name.includes('Грудные водки') ||
            name.includes('Персиковые водки') ||
            name.includes('Водки, называемые крамбамбули') ||
            name.includes('Мастичные водки') ||
            name.includes('Водки от колики') ||
            name.includes('Водки укрепительные') ||
            name.includes('Водки ореховые') ||
            name.includes('Водки Игуменские') ||
            name.includes('Розолии') ||
            name.includes('Воздушные водки') ||
            name.includes('Кардамонные водки') ||
            name.includes('Водки для здоровья') ||
            name.includes('Ратафии') ||
            name.includes('Христофлеты') ||
            name.includes('Водки хлебные') ||
            name.includes('Водки оранжевые') ||
            name.includes('Водки серебряные') ||
            name.includes('Водки золотые') ||
            name.includes('Водки горькия') ||
            content.length < 100) {
          continue;
        }

        // Проверяем, что это действительно рецепт
        if (name.length > 3 && content.length > 50) {
          recipes.push({
            id: `{number}`,
            number: number,
            name: name,
            content: content,
            full_text: `${name}\n\n${content}`
          });

          console.log(`Найден рецепт ${number}: "${name}"`);
          foundCount++;
        }
      }

      console.log(`Основным паттерном найдено: ${recipes.length} рецептов`);

      // Дополнительный поиск рецептов без двойных звездочек
      if (recipes.length < 100) {
        console.log('Поиск дополнительных рецептов...');

        const additionalPattern = /^(\d+)\.\s*([А-Яа-яёЁ][^\n]{10,100}?)\.\s*$([\s\S]*?)(?=^\d+\.\s*[А-Яа-яёЁ]|$)/gm;
        let additionalMatch;

        while ((additionalMatch = additionalPattern.exec(text)) !== null) {
          const number = parseInt(additionalMatch[1]);
          const name = additionalMatch[2].trim();
          const content = additionalMatch[3].trim();

          // Проверяем, не добавили ли уже этот рецепт
          if (!recipes.some(r => r.number === number) && content.length > 100) {
            recipes.push({
              id: `recipe_${number}`,
              number: number,
              name: name,
              content: content,
              full_text: `${name}\n\n${content}`
            });

            console.log(`Дополнительно найден рецепт ${number}: "${name}"`);
          }
        }
      }

    } catch (parseError) {
      console.log('Ошибка парсинга:', parseError.message);
    }

    return recipes;
  }

  // Расширенная генерация sparse векторов на основе анализа документа
  function generateComprehensiveSparseVectors(recipeText, recipeName) {
    const vocabularies = {
      ingredients: [
        // Алкогольные основы
        'водка', 'спирт', 'хлебное вино', 'простое вино', 'рейнское вино', 
        'французская водка', 'двойная водка', 'виноградное вино',

        // Орехи и семена
        'горький миндаль', 'сладкий миндаль', 'персиковые ядра', 'сливовые ядра', 
        'вишнёвые ядра', 'абрикосовые ядра', 'кедровые орехи',

        // Фрукты и ягоды
        'изюм', 'винные ягоды', 'коринка', 'можжевеловые ягоды', 'лавровые ягоды',
        'ягоды чёрного шиповника', 'ягоды красного шиповника', 'финики',
        'вишни', 'малина', 'смородина', 'ежевика', 'земляника', 'померанцы', 'лимоны',

        // Корки и цветы цитрусовых
        'лимонная корка', 'померанцевая корка', 'померанцевые цветы',

        // Подсластители
        'сахар', 'сироп', 'мёд', 'сахарный песок', 'леденец',

        // Жидкости
        'вода', 'розовая вода', 'колодезная вода', 'мелиссовая вода', 'коричная вода'
      ],

      spices_herbs: [
        // Основные специи
        'корица', 'анис', 'гвоздика', 'кориандр', 'кишнец', 'кардамон', 'имбирь',
        'мускатный орех', 'мускатный цвет', 'мацис', 'шафран', 'бадьян', 'тмин',
        'галган', 'галангал', 'калган', 'фенхель', 'райские зёрна', 'перец кубеба',
        'ямайский перец', 'длинный перец', 'чёрный перец', 'соль винного камня',
        'кремортартар', 'поваренная соль',

        // Лекарственные травы
        'девясил', 'мать-и-мачеха', 'подбел', 'иссоп', 'шалфей', 'мелисса',
        'майоран', 'розмарин', 'аир', 'ир', 'горечавка', 'полынь', 'рута',
        'чабрец', 'кудрявая мята', 'ромашка', 'римская ромашка', 'лавандовые цветы',
        'вероника', 'пижма', 'базилик', 'тысячелистник', 'буквица', 'ангелика',
        'дягиль', 'кардобенедикт', 'кникус благословенный', 'золототысячник',

        // Корни
        'солодковый корень', 'солодка', 'лакрица', 'фиалковый корень', 'ирисовый корень',
        'цитварный корень', 'бедренцовый корень', 'корень девясила', 'корень дягиля',
        'корень ангелики', 'валериана', 'хрен',

        // Цветы
        'розовые цветы', 'коричные цветы', 'цветы гвоздичного дерева',
        'цветы корицы', 'цветы кассии', 'цветы розмарина', 'цветы ландыша',
        'бузинные цветы',

        // Особые компоненты
        'ладан', 'стиракс', 'сассафрас', 'мастика', 'мирра', 'бензойная смола',
        'амбра', 'мускус', 'бобровая струя', 'кора винтера', 'винтеранская корка',
        'буковая зола', 'поташ', 'квасцы', 'ревень', 'алоэ', 'сабур'
      ],

      techniques: [
        // Подготовка ингредиентов
        'возьмите', 'истолочь', 'покрошить', 'раздробить', 'измельчить', 'смолоть',
        'обжарить', 'крошить', 'толочь', 'мелко истолочь', 'крупновато истолочь',
        'очистить', 'срезать', 'соскрести',

        // Настаивание
        'настаивать', 'настоять', 'сложить в бутыль', 'положить в бутыль',
        'налить', 'умеренная теплота', 'умеренное тепло', 'закупоренная бутыль',
        'заткнуть', 'дни', 'недели', 'сутки',

        // Перегонка
        'перегнать', 'перегонный куб', 'перегнанный спирт', 'дистиллят',
        'переложить в куб', 'выложить в куб', 'прибавить воды', 'добавить воды',

        // Финишная обработка
        'подсластить', 'подцветить', 'подкрасить', 'процедить', 'пропустить',
        'цедильная бумага', 'фильтровальная бумага', 'сварить сироп', 'разварить',
        'слить', 'сцедить', 'отстояться', 'выдержать',

        // Брожение
        'бродить', 'дрожжи', 'сусло', 'перебродить', 'пивные дрожжи',
        'кисловатый запах', 'брожение'
      ],

      categories: [
        // Основные типы
        'розолия', 'воздушная водка', 'водка для здоровья', 'желудочная водка',
        'грудная водка', 'карминативная водка', 'ароматная водка', 'укрепительная водка',
        'синяя водка', 'кардамонная водка', 'кофейная водка', 'персиковая водка',
        'ореховая водка', 'игуменская водка', 'абтвассер', 'ратафия', 'крамбамбули',
        'мастичная водка', 'христофлет', 'мараскино',

        // По происхождению
        'хемницкая', 'гданская', 'бреславская', 'польская', 'линдавская',
        'венгерская', 'итальянская', 'французская', 'английская', 'испанская',
        'венская', 'нюрнбергская', 'курсаксонская', 'лондонская', 'туринская',
        'кёльнская', 'швабская', 'мангеймская', 'франкфуртская',

        // По качеству
        'лучшая', 'добрая', 'отборная', 'хорошая', 'двойная', 'тройная',
        'простая', 'обыкновенная', 'свежая', 'доброго', 'первого рода',
        'второго рода', 'третьего рода', 'иного рода', 'другого рода',

        // Специальные названия
        'императорская', 'королевская', 'адмиральская', 'кармелитская',
        'небесная вода', 'святая вода', 'магдалинина', 'госпобова',
        'вода смелости', 'любовная', 'молодецкая', 'девическая', 'супружеская'
      ],

      measurements: [
        // Старинные меры веса
        'золотник', 'фунт', 'грана', 'скрупул', 'пуд', 'лот',

        // Старинные меры объёма
        'штоф', 'ведро', 'бутыль', 'бутылка', 'гарнец', 'четверик',
        'ложка', 'стакан', 'горсть', 'щепоть',

        // Временные промежутки
        '8 дней', '10 дней', '12 дней', '14 дней', 'две недели', 'три недели',
        'несколько дней', 'сутки', 'двое суток', 'час', 'ночь',

        // Количественные указания
        'по', 'около', 'без четверти', 'с четвертью', 'полтора', 'полфунта',
        'два с четвертью', 'три с половиной', 'четыре с половиной',
        'дюжина', 'десяток', 'горсти', 'капли'
      ]
    };

    const result = {
      ingredients: { indices: [], values: [] },
      spices_herbs: { indices: [], values: [] },
      techniques: { indices: [], values: [] },
      categories: { indices: [], values: [] },
      measurements: { indices: [], values: [] }
    };

    const text = (recipeText + ' ' + recipeName).toLowerCase();

    Object.keys(vocabularies).forEach(category => {
      vocabularies[category].forEach((term, index) => {
        const normalizedTerm = term.toLowerCase();
        if (text.includes(normalizedTerm)) {
          result[category].indices.push(index);

          // Подсчитываем частоту с учётом различных форм слова
          const regex = new RegExp(normalizedTerm.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'g');
          const frequency = (text.match(regex) || []).length;

          // Применяем веса по важности категории
          let weight = frequency;
          if (category === 'ingredients' || category === 'spices_herbs') {
            weight *= 2.0; // Ингредиенты и специи самые важные
          } else if (category === 'categories') {
            weight *= 1.8; // Категории очень важны
          } else if (category === 'techniques') {
            weight *= 1.3; // Техники важны
          }

          result[category].values.push(weight);
        }
      });
    });

    return result;
  }

  // Парсим все рецепты
  const allRecipes = parseAllWaterRecipes(fullText);
  console.log(`ВСЕГО НАЙДЕНО РЕЦЕПТОВ: ${allRecipes.length}`);

  if (allRecipes.length === 0) {
    console.log('=== НЕ НАЙДЕНО РЕЦЕПТОВ - ОТЛАДКА ===');
    console.log('Первые 2000 символов:');
    console.log(fullText.substring(0, 2000));

    return [{ json: { 
      error: 'No recipes found',
      debug_info: {
        text_length: fullText.length,
        sample_text: fullText.substring(0, 2000)
      }
    }}];
  }

  // Сортируем рецепты по номерам
  allRecipes.sort((a, b) => a.number - b.number);

  // Обрабатываем все найденные рецепты
  const processedRecipes = allRecipes.map((recipe, index) => {
    if (index % 50 === 0) {
      console.log(`Обрабатываем рецепт ${index + 1}/${allRecipes.length}: ${recipe.name}`);
    }

    return {
      ...recipe,
      sparse_vectors: generateComprehensiveSparseVectors(recipe.content, recipe.name)
    };
  });

  console.log('=== ОБРАБОТКА ЗАВЕРШЕНА ===');
  console.log(`Успешно обработано: ${processedRecipes.length} рецептов`);
  console.log(`Диапазон номеров: ${processedRecipes[0]?.number} - ${processedRecipes[processedRecipes.length - 1]?.number}`);

  // Показываем статистику по типам рецептов
  const categoryCount = {};
  processedRecipes.forEach(recipe => {
    const name = recipe.name.toLowerCase();
    if (name.includes('водка')) categoryCount['водка'] = (categoryCount['водка'] || 0) + 1;
    else if (name.includes('розолия')) categoryCount['розолия'] = (categoryCount['розолия'] || 0) + 1;
    else if (name.includes('ратафия')) categoryCount['ратафия'] = (categoryCount['ратафия'] || 0) + 1;
    else categoryCount['другое'] = (categoryCount['другое'] || 0) + 1;
  });

  console.log('Статистика по типам:');
  Object.entries(categoryCount).forEach(([type, count]) => {
    console.log(`  ${type}: ${count} рецептов`);
  });

  console.log('Первые 10 рецептов:');
  processedRecipes.slice(0, 10).forEach(r => {
    console.log(`  ${r.number}. ${r.name}`);
  });

  return processedRecipes.map(recipe => ({ json: recipe }));

} catch (globalError) {
  console.log('КРИТИЧЕСКАЯ ОШИБКА:', globalError.message);
  console.log('Стек ошибки:', globalError.stack);

  return [{ json: { 
    error: 'Critical parsing error',
    message: globalError.message,
    stack: globalError.stack
  }}];
}

// Code Node: Объединение sparse и dense векторов (ИСПРАВЛЕННЫЙ)
// Убираем function declaration, выполняем код напрямую

// Получаем данные запроса и ответ OpenAI
const openaiResponse = $input.last().json; // Ответ от OpenAI

// Извлекаем эмбеддинг
if (!openaiResponse.data || !Array.isArray(openaiResponse.data) || openaiResponse.data.length === 0) {
  throw new Error('Некорректный ответ от OpenAI');
}

const embedding = openaiResponse.data[0].embedding;
if (!Array.isArray(embedding)) {
  throw new Error('Эмбеддинг не является массивом');
}

const recipe = $('Code1').first().json.recipe_data;

// Подготавливаем sparse векторы
const sparseVectors = {};
if (recipe.sparse_vectors) {
  Object.keys(recipe.sparse_vectors).forEach(category => {
    const sparse = recipe.sparse_vectors[category];
    if (sparse && sparse.indices && sparse.values && sparse.indices.length > 0) {
      sparseVectors[category] = {
        indices: sparse.indices,
        values: sparse.values
      };
    }
  });
}

const uniqueId = recipe.number * 1000 + Date.now() % 1000;


// Создаем point для Qdrant
const point = {
  id:  Math.abs(uniqueId),  // ИСПРАВЛЕНО: используем числовой ID вместо строки
  vector: {
    dense: embedding,
    ...sparseVectors
  },
  payload: {
    recipe_id: recipe.id,  // Сохраняем оригинальный строковый ID в payload
    recipe_number: recipe.number,
    recipe_name: recipe.name,
    content: recipe.content,
    full_text: recipe.full_text,
    content_length: recipe.content?.length || 0,
    name_lower: recipe.name?.toLowerCase() || '',
    has_ingredients: !!sparseVectors.ingredients,
    has_spices_herbs: !!sparseVectors.spices_herbs,
    has_techniques: !!sparseVectors.techniques,
    has_measurements: !!sparseVectors.measurements,
    is_vodka: recipe.name?.toLowerCase().includes('водка') || false,
    is_rozolia: recipe.name?.toLowerCase().includes('розолия') || false,
    is_ratafia: recipe.name?.toLowerCase().includes('ратафия') || false,
    created_at: new Date().toISOString(),
    vector_dimension: embedding.length,
    sparse_categories: Object.keys(sparseVectors)
  }
};

console.log(`✅ Point создан для рецепта ${recipe.id} с числовым ID ${recipe.number}`);

// Возвращаем point для загрузки в Qdrant
return [{
  json: {
    points: [point]  // Qdrant ожидает массив points
  }
}];
